-- iranapp-api: 18 migrations for the production database (inherited from ghollacLaravel).
-- Run once in phpMyAdmin (Import, or SQL tab) on the production database, after a backup.
-- Everything here only adds tables, nullable/defaulted columns and indexes;
-- the old backend keeps working afterwards.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `migrations` (`id` int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY, `migration` varchar(255) NOT NULL, `batch` int NOT NULL) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @iranapp_batch = (SELECT IFNULL(MAX(`batch`), 0) + 1 FROM `migrations`);

create table `personal_access_tokens` (`id` bigint unsigned not null auto_increment primary key, `tokenable_type` varchar(255) not null, `tokenable_id` bigint unsigned not null, `name` text not null, `token` varchar(64) not null, `abilities` text null, `last_used_at` timestamp null, `expires_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `personal_access_tokens` add index `personal_access_tokens_tokenable_type_tokenable_id_index`(`tokenable_type`, `tokenable_id`);
alter table `personal_access_tokens` add unique `personal_access_tokens_token_unique`(`token`);
alter table `personal_access_tokens` add index `personal_access_tokens_expires_at_index`(`expires_at`);

alter table `ads` add `video` varchar(191) null after `notes`;

create table `ads_view` (`id` int unsigned not null auto_increment primary key, `ads_id` int unsigned not null, `user_id` int unsigned null, `created_at` datetime not null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `ads_view` add index `ads_id_created_at`(`ads_id`, `created_at`);
alter table `ads_view` add constraint `ads_view_ibfk_1` foreign key (`ads_id`) references `ads` (`id`) on delete cascade on update cascade;
alter table `ads_view` add constraint `ads_view_ibfk_2` foreign key (`user_id`) references `users` (`id`) on delete set null on update cascade;
alter table `ads_view` add index `user_id`(`user_id`);

create table `admin_notifications` (`id` int unsigned not null auto_increment primary key, `ads_id` int unsigned not null, `valid_until` date not null, `read_at` datetime null, `created_at` datetime not null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `admin_notifications` add unique `ads_id_valid_until`(`ads_id`, `valid_until`);
alter table `admin_notifications` add constraint `admin_notifications_ibfk_1` foreign key (`ads_id`) references `ads` (`id`) on delete cascade on update cascade;
alter table `admin_notifications` add index `read_at`(`read_at`);

create table `ad_terms_acceptances` (`id` int unsigned not null auto_increment primary key, `user_id` int unsigned not null, `ad_type` varchar(20) not null, `ad_id` int unsigned not null, `terms_version` varchar(40) not null, `accepted_at` timestamp not null, `ip_address` varchar(45) null, `app_version` varchar(40) null, `user_agent` varchar(255) null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `ad_terms_acceptances` add index `ad_terms_acceptances_ad_type_ad_id_index`(`ad_type`, `ad_id`);
alter table `ad_terms_acceptances` add index `ad_terms_acceptances_user_id_index`(`user_id`);

alter table `news` add `publish_at` datetime null;
alter table `news` add `notify_on_publish` tinyint(1) not null default '0';
alter table `news` add index `news_publish_at_index`(`publish_at`);
update `news` set `publish_at` = created_at;

alter table `users` add `role` enum('normal', 'pro') not null default 'normal' after `type`;
alter table `users` add `pro_since` timestamp null after `role`;

create table `e_contracts` (`id` int unsigned not null auto_increment primary key, `user_id` int unsigned not null, `status` enum('pending', 'approved', 'rejected') not null default 'pending', `business_type` varchar(20) not null, `business_name` varchar(200) not null, `manager_title` varchar(10) not null, `manager_name` varchar(200) not null, `national_code` char(10) not null, `phone` varchar(20) not null, `mobile` varchar(11) not null, `address` text not null, `subject` varchar(255) not null, `start_date` char(10) not null, `end_date` char(10) not null, `duration_months` tinyint unsigned not null, `starts_on` date not null, `ends_on` date not null, `discount_percent` tinyint unsigned not null, `contract_date` char(10) not null, `template_version` varchar(20) not null, `contract_text` text not null, `terms_accepted_at` timestamp not null, `ip_address` varchar(45) null, `app_version` varchar(40) null, `user_agent` varchar(255) null, `rejection_reason` text null, `reviewed_by` int unsigned null, `reviewed_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `e_contracts` add index `e_contracts_user_id_id_index`(`user_id`, `id`);
alter table `e_contracts` add index `e_contracts_status_index`(`status`);
alter table `e_contracts` add constraint `e_contracts_user_id_foreign` foreign key (`user_id`) references `users` (`id`);

create table `app_installs` (`id` int unsigned not null auto_increment primary key, `install_id` varchar(64) not null, `source` varchar(20) not null, `installer_package` varchar(150) null, `is_upgrade` tinyint(1) not null default '0', `app_version` varchar(40) null, `android_version` varchar(20) null, `device_model` varchar(100) null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `app_installs` add index `app_installs_created_at_index`(`created_at`);
alter table `app_installs` add index `app_installs_source_created_at_index`(`source`, `created_at`);
alter table `app_installs` add unique `app_installs_install_id_unique`(`install_id`);

alter table `users` add `birth_date` date null after `last_name`;

-- 2026_09_27_140000_convert_ad_tables_to_utf8mb4
ALTER TABLE `ads` CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `vehicles_ads` CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `estates_ads` CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `employs_ads` CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_persian_ci;

create table `membership_cards` (`id` int unsigned not null auto_increment primary key, `user_id` int unsigned not null, `serial_number` bigint unsigned not null, `status` enum('pending', 'approved', 'rejected') not null default 'pending', `members` text not null, `membership_date` char(10) not null, `expiry_date` char(10) not null, `starts_on` date not null, `expires_on` date not null, `app_version` varchar(40) null, `submitted_at` timestamp not null, `rejection_reason` text null, `reviewed_by` int unsigned null, `reviewed_at` timestamp null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `membership_cards` add index `membership_cards_status_index`(`status`);
alter table `membership_cards` add constraint `membership_cards_user_id_foreign` foreign key (`user_id`) references `users` (`id`);
alter table `membership_cards` add unique `membership_cards_user_id_unique`(`user_id`);
alter table `membership_cards` add unique `membership_cards_serial_number_unique`(`serial_number`);

create table `e_contract_templates` (`id` int unsigned not null auto_increment primary key, `version` varchar(20) not null, `title` varchar(200) not null, `sections` text not null, `created_by` int unsigned null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `e_contract_templates` add unique `e_contract_templates_version_unique`(`version`);

create table `phone_book_entries` (`id` int unsigned not null auto_increment primary key, `full_name` varchar(150) null, `phone` varchar(20) not null, `guild` varchar(150) null, `created_at` timestamp null, `updated_at` timestamp null) default character set utf8mb4 collate 'utf8mb4_unicode_ci';
alter table `phone_book_entries` add index `phone_book_entries_guild_index`(`guild`);
alter table `phone_book_entries` add unique `phone_book_entries_phone_unique`(`phone`);

alter table `e_contracts` modify `status` enum('pending', 'awaiting_payment', 'payment_submitted', 'approved', 'rejected') not null default 'pending';
alter table `e_contracts` add `billing` varchar(10) null after `status`;
alter table `e_contracts` add `amount` bigint unsigned null after `billing`;
alter table `e_contracts` add `card_number` varchar(16) null after `amount`;
alter table `e_contracts` add `card_holder` varchar(100) null after `card_number`;
alter table `e_contracts` add `payment_message` text null after `card_holder`;
alter table `e_contracts` add `payment_requested_at` timestamp null after `payment_message`;
alter table `e_contracts` add `payment_reference` varchar(100) null after `payment_requested_at`;
alter table `e_contracts` add `payment_submitted_at` timestamp null after `payment_reference`;
alter table `e_contracts` add `payment_rejection_reason` text null after `payment_submitted_at`;
alter table `e_contracts` add `expiry_notified_at` timestamp null after `reviewed_at`;
alter table `e_contracts` add index `e_contracts_status_ends_on_index`(`status`, `ends_on`);
update `e_contracts` set `billing` = 'free' where `status` = 'approved';

alter table `admin_notifications` modify `ads_id` int unsigned null;
alter table `admin_notifications` add `e_contract_id` int unsigned null after `ads_id`;
alter table `admin_notifications` add unique `e_contract_id_valid_until`(`e_contract_id`, `valid_until`);
alter table `admin_notifications` add constraint `admin_notifications_e_contract_id_foreign` foreign key (`e_contract_id`) references `e_contracts` (`id`) on delete cascade;

alter table `membership_cards` add `national_code` char(10) null after `members`;

update `membership_cards` set `serial_number` = serial_number + 10000000 where `serial_number` >= 1394001003631900 and `serial_number` < 1394001013631900;

